import React from 'react';
import {
  Box,
  Typography,
  IconButton,
  Paper,
  Stack,
  useTheme
} from '@mui/material';
import {
  Savings,
  AccountBalanceWallet,
  Payment,
  PersonOutline
} from '@mui/icons-material';
import { Link, useNavigate } from 'react-router-dom';

const menuItems = [
  { label: 'จองสินค้า', path: 'downPayment', icon: <Savings /> },
  { label: 'สินเชื่อ', path: 'loan', icon: <AccountBalanceWallet /> },
  { label: 'ชำระเงิน', path: 'paid', icon: <Payment /> },
  { label: 'ข้อมูลส่วนตัว', path: 'profile', icon: <PersonOutline /> },
];

const HomeMenu = () => {
  const theme = useTheme();
  const navigate = useNavigate();

  return (
    <Box p={3}>
      <Box
        display="flex"
        flexWrap="wrap"
        justifyContent="center"
        gap={2}
      >
        {menuItems.map((item) => (
          <Link key={item.path} to={item.path} style={{ textDecoration: 'none' }}>
            <Paper
              elevation={1}
              sx={{
                width: 120,
                height: 120,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                background: theme.palette.background.default,
              }}
            >
              <IconButton color="info" sx={{fontSize:48}}>{item.icon}</IconButton>
              <Typography variant="body2" mt={1} color="info">
                {item.label}
              </Typography>
            </Paper>
          </Link>
        ))}
      </Box>
    </Box>
  );
};

export default HomeMenu;
